// ---- Shared helpers (same block in every FS Code node) ----
const str = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const truthy = (v) => v === true || ['TRUE', 'YES', 'Y', '1'].includes(str(v).toUpperCase());
const FIELD_TYPES = ['text', 'longtext', 'email', 'phone', 'number', 'date', 'dropdown', 'checkbox'];

function normalizeEvents(rows) {
  return rows
    .filter((r) => str(r.event_id))
    .map((r) => ({
      event_id: str(r.event_id),
      event_name: str(r.event_name) || str(r.event_id),
      target_tab: str(r.target_tab) || ('Data_' + str(r.event_id)),
      is_default: truthy(r.is_default),
      // a blank "active" cell counts as active
      active: str(r.active) === '' ? true : truthy(r.active),
    }));
}

function normalizeFields(rows, eventId) {
  const seen = new Set();
  return rows
    .filter((r) => str(r.event_id) === eventId && str(r.field_key))
    .map((r, i) => {
      const type = str(r.field_type).toLowerCase();
      const order = Number(str(r.order));
      return {
        key: str(r.field_key),
        label: str(r.form_label) || str(r.field_key),
        type: FIELD_TYPES.includes(type) ? type : 'text',
        required: truthy(r.required),
        options: str(r.options).split(/[,|]/).map((o) => o.trim()).filter(Boolean),
        hint: str(r.ai_hint),
        order: Number.isFinite(order) && str(r.order) !== '' ? order : 1000 + i,
      };
    })
    .sort((a, b) => a.order - b.order)
    .filter((f) => (seen.has(f.key) ? false : seen.add(f.key)));
}

// Normalizes a single value to the format that gets stored in the sheet.
function cleanValue(field, value) {
  let v = str(value);
  switch (field.type) {
    case 'email':
      return v.replace(/\s+/g, '').toLowerCase();
    case 'phone':
      return v.replace(/[^\d+]/g, '');
    case 'checkbox':
      return v === '' ? '' : (truthy(v) || ['CHECKED', 'X', '✓', '✔'].includes(v.toUpperCase()) ? 'TRUE' : 'FALSE');
    case 'dropdown': {
      const match = field.options.find((o) => o.toLowerCase() === v.toLowerCase());
      return match || v;
    }
    default:
      return v;
  }
}
// ---- End shared helpers ----

// Validates the confirmed values and builds the sheet row.
const fail = (error) => [{ json: { ok: false, error } }];

const body = $('Webhook').first().json.body || {};
const eventId = str(body.event_id);
const values = body.values && typeof body.values === 'object' ? body.values : null;
const aiValues = body.ai_values && typeof body.ai_values === 'object' ? body.ai_values : null;

if (!eventId) return fail('No event selected.');
if (!values) return fail('No values received.');

const event = normalizeEvents($('Read Events').all().map((i) => i.json)).find((e) => e.event_id === eventId);
if (!event || !event.active) return fail(`Event ${eventId} was not found or is inactive.`);

const fields = normalizeFields($('Read Fields').all().map((i) => i.json), eventId);
if (!fields.length) return fail(`Event ${eventId} has no field mapping.`);

const row = {
  timestamp: DateTime.now().setZone('Asia/Manila').toFormat('yyyy-MM-dd HH:mm:ss'),
  event_id: eventId,
};
const errors = [];
let edited = false;

for (const f of fields) {
  const v = cleanValue(f, values[f.key]);
  if (f.required && !v) errors.push(`${f.label} is required.`);
  if (f.type === 'email' && v && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)) errors.push(`${f.label} is not a valid email.`);
  if (f.type === 'dropdown' && v && f.options.length && !f.options.includes(v)) errors.push(`${f.label} must be one of: ${f.options.join(', ')}.`);
  if (aiValues && cleanValue(f, aiValues[f.key]) !== v) edited = true;
  row[f.key] = v;
}

if (errors.length) return fail(errors.join(' '));

row.edited = aiValues ? (edited ? 'YES' : 'NO') : '';

return [{ json: { ok: true, target_tab: event.target_tab, row } }];
